styles:
.w-webflow-badge, a.w-webflow-badge{display:none!important;visibility:hidden!important;pointer-events:none!important}

/* About page: color-only alignment with WDS homepage. */
:root {
 --wds-theme-navy:#122c4e;
 --wds-theme-red:#d90000;
 --wds-brand-blue-medium:#36577e;
 --wds-brand-blue-light:#a9bdd6;
 --wds-brand-blue-soft:#e7eef7;
 --wds-brand-blue-pale:#f1f5fa;
 --_colors---background-color--blue-color:#122c4e;
 --_colors---text-color--electric-blue:#122c4e;
 --_colors---background-color--hyper-blue:#122c4e;
 --_colors---background-color--sky-blue:#e7eef7;
 --_colors---background-color--blue-light:#c4d4e7;
 --_colors---background-color--ice-sky:#e9eff7;
 --_colors---background-color--morning-haze:#dce6f2;
 --_colors---background-color--powder-blue:#a9bdd6;
 --_colors---background-color--orange:#ff5100;
 --_colors---background-color--orange-light:#ff933d;
 --_colors---background-color--soft-orange:#f7f2f0;
}
.blue-text{color:#122c4e}
.section.growth-channels,.wrapper.team,.mission-card.active,.looking-card{background-color:#122c4e}
.section.growth-channels :is(.growth-title,.chart-text){color:#fff}
.section.growth-channels .sub-header[data-wds--sub-header--variant="orange"]{background-color:#d90000;color:#fff}
.section.growth-channels .sub-header[data-wds--sub-header--variant="orange"] .sub-para{color:#fff}
body .primary-button[data-wds--primary-button--variant="orange-light"]{background-color:#122c4e;color:#fff}
body .primary-button[data-wds--primary-button--variant="orange-light"] :is(.button-text,.button-arrow,.button-arrows,.button-texts){color:#fff}
.section.home-hero .hero-buttons .primary-button[data-wds--primary-button--variant="orange-light"],
.section.cta .cta-buttons .primary-button[data-wds--primary-button--variant="orange-light"]{background-color:#d90000!important;color:#fff!important}
body .primary-button .button-bg{background-color:#d90000!important}
body .primary-button:is(:hover,:focus-visible){background-color:#d90000!important;color:#fff!important}
body .primary-button:is(:hover,:focus-visible) :is(.button-text,.button-arrow,.button-arrows,.button-texts){color:#fff!important}
body :is(.secondary-button,.check-button,.case-link,.social-link,.team-social,.menu-button,.w-button):is(:hover,:focus-visible){background-color:#d90000!important;color:#fff!important}
body :is(.secondary-button,.check-button,.case-link,.social-link,.team-social,.menu-button,.w-button):is(:hover,:focus-visible) :is(.secondary-arrow,.social-icon,svg){color:#fff!important}
body .primary-button:focus-visible{outline-color:#d90000}
body .w-button{background-color:#122c4e}
body :is(.w-input,.w-select):focus{border-color:#122c4e}
body :is(.w-dropdown-link,.w-nav-link).w--current{color:#122c4e}
.footer :is(.page-link,.copyright-link):is(:hover,:focus-visible){color:#ff933d}
.section.cta .cta-line{background-color:#122c4e}
.section.cta .blue-text{color:#122c4e!important}
.section.cta .cta-card{background-color:#fff}
img.sub-arrow[src$="6a6bdef8f4ecd6b9986148c5_Arrow.png"]{filter:brightness(0) saturate(100%) invert(13%) sepia(95%) saturate(7000%) hue-rotate(357deg) brightness(85%) contrast(120%)}
